"import os

def write_case_file(path, content):
    """Helper function to write content to a file, creating directories if needed."""
    dir_name = os.path.dirname(path)
    if dir_name:
        os.makedirs(dir_name, exist_ok=True)
    with open(path, "w") as f:
        f.write(content)

